<div class="dashboard-heading"><div><span class="eyebrow"><?= e($currentStore['name']) ?></span><h2>Financeiro da loja</h2><p>Faturamento, comissão e valor líquido.</p></div></div><?php $cards=[['label'=>'Faturamento bruto','value'=>'R$ '.number_format((float)$summary['gross'],2,',','.')],['label'=>'Comissões','value'=>'R$ '.number_format((float)$summary['commissions'],2,',','.')],['label'=>'Líquido','value'=>'R$ '.number_format((float)$summary['net'],2,',','.')],['label'=>'Pedidos','value'=>(int)$summary['orders']]];?><div class="stat-grid"><?php foreach($cards as $stat)require dirname(__DIR__,2).'/components/dashboard/stat-card.php';?></div><section class="panel"><div class="panel-head"><h3>Movimentações</h3></div><div class="table-wrap"><table><thead><tr><th>Subpedido</th><th>Produtos</th><th>Comissão</th><th>Líquido</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $order):?><tr><td><?= e($order['code']) ?></td><td>R$ <?= number_format((float)$order['products_total'],2,',','.') ?></td><td>R$ <?= number_format((float)$order['commission_total'],2,',','.') ?></td><td>R$ <?= number_format((float)$order['seller_net_total'],2,',','.') ?></td><td><?php $status=$order['status'];require dirname(__DIR__,2).'/components/dashboard/status-badge.php';?></td></tr><?php endforeach;?></tbody></table></div></section>
